function Nav() {
  const [active, setActive] = useState("");
  useEffect(() => {
    const ids = ["snapshot", "work", "story", "about", "process", "contact"];
    const els = ids.map((i) => document.getElementById(i)).filter(Boolean);
    if (!els.length || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver((entries) => {
      const vis = entries.filter((e) => e.isIntersecting)
        .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
      if (vis) setActive(vis.target.id);
    }, { threshold: [0.15, 0.4], rootMargin: "-20% 0px -60% 0px" });
    els.forEach((e) => io.observe(e));
    return () => io.disconnect();
  }, []);
  const link = (href, label, cls = "") => (
    <a href={`#${href}`} className={`${cls}${active === href ? " on" : ""}`}>{label}</a>
  );
  return (
    <nav className="nav" aria-label="Primary">
      <span className="mark">(JD)</span>
      <span className="bar" aria-hidden="true" />
      <div className="nav-links">
        {link("work", "Work")}
        {link("about", "About", "hide-s")}
        {link("story", "Experience", "hide-s")}
        {link("contact", "Contact")}
        <span className="plus" aria-hidden="true">+</span>
      </div>
    </nav>
  );
}

