function Work({ onOpen }) {
  const fine = useFine();
  const [hover, setHover] = useState(null);
  const card = useRef(null);
  const target = useRef({ x: 0, y: 0 });

  useEffect(() => {
    if (!fine || reduced()) return;
    let raf = 0; const cur = { x: 0, y: 0 };
    const move = (e) => { target.current = { x: e.clientX, y: e.clientY }; };
    const loop = () => {
      cur.x += (target.current.x - cur.x) * 0.16;
      cur.y += (target.current.y - cur.y) * 0.16;
      if (card.current) card.current.style.transform = `translate(${cur.x}px, ${cur.y}px)`;
      raf = requestAnimationFrame(loop);
    };
    window.addEventListener("mousemove", move, { passive: true });
    raf = requestAnimationFrame(loop);
    return () => { window.removeEventListener("mousemove", move); cancelAnimationFrame(raf); };
  }, [fine]);

  const p = PROJECTS.find((x) => x.id === hover);

  return (
    <section className="sec" id="work">
      <div className="wrap">
        <R className="shead">
          <div>
            <p className="ann" style={{ marginBottom: 6 }}>case files</p>
            <h2 className="dsp">Selected<br />work.</h2>
          </div>
          <span className="idx">[ Researched · questioned · redesigned · tested · shipped ]</span>
        </R>

        {PROJECTS.map((pr, i) => (
          <R key={pr.id} d={Math.min(3, i + 1)}>
            <a className="row" href={`#${pr.id}`}
              onClick={(e) => { e.preventDefault(); onOpen(pr.id); }}
              onMouseEnter={() => setHover(pr.id)}
              onMouseLeave={() => setHover(null)}
              onFocus={() => setHover(pr.id)} onBlur={() => setHover(null)}>
              <span className="row-n">{pr.n}</span>
              <div>
                <h3>{pr.name}</h3>
                <span className="row-cat">{pr.cat}</span>
              </div>
              <p style={{ fontSize: ".94rem" }}>{pr.head}</p>
              <div className="row-metric">
                <b>{pr.metrics[0][0]}</b><span>{pr.metrics[0][1]}</span>
              </div>
              <span className="row-go" aria-hidden="true"><ArrowUR s={22} /></span>
            </a>
          </R>
        ))}
      </div>

      {fine && (
        <div className={`preview${hover ? " on" : ""}`} ref={card} aria-hidden="true">
          <div className="preview-in">
            <div className="preview-art" style={{ background: p ? p.tint : "var(--paper)" }}>
              {p && p.shot ? <img src={p.shot} alt="" /> : <b>{p ? p.n : ""}</b>}
            </div>
            <div className="preview-cap">
              <span>{p ? p.name : ""}</span>
              <span className="red">View case ↗</span>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

