/* ============================================================
   CONTACT + FINAL FRAME
   ============================================================ */

function Contact() {
  const [ref, seen] = useInView(0.3);
  const [struck, setStruck] = useState(false);
  const [cont, setCont] = useState(false);
  useEffect(() => {
    if (!seen) return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion:reduce)").matches;
    if (reduce) { setStruck(true); setCont(true); return; }
    const a = setTimeout(() => setStruck(true), 650);
    const b = setTimeout(() => setCont(true), 1400);
    return () => { clearTimeout(a); clearTimeout(b); };
  }, [seen]);

  return (
    <section className="dark" id="contact" ref={ref}>
      <div className="wrap sec">
        <R><p className="narration" style={{ color: "var(--paper)", marginBottom: 24 }}>Well… you made it to the end.</p></R>
        <R d={1}><div className="bubble" style={{ marginBottom: 34 }}>"That's commitment."</div></R>
        <R d={1}>
          <h2 className="dsp" style={{ fontSize: "clamp(2.4rem,8.6vw,7.4rem)", marginBottom: 34 }}>
            Have a problem<br />worth designing?<br /><span className="red">Let's talk.</span>
          </h2>
        </R>
        <R d={2} style={{ display: "flex", gap: 26, flexWrap: "wrap", alignItems: "flex-end", justifyContent: "space-between" }}>
          <a className="mail" href="mailto:hello@example.com">Email me <ArrowUR s={22} /></a>
          <div style={{ display: "flex", gap: 24, flexWrap: "wrap" }}>
            {["LinkedIn", "Resume", "Behance"].map((l) => (
              <a key={l} href="#" className="lbl" style={{ borderBottom: "1px solid rgba(244,243,241,.4)", paddingBottom: 5 }}>{l} ↗</a>
            ))}
          </div>
        </R>
        <R d={3} style={{ marginTop: 34 }}>
          <p className="hand" style={{ fontSize: "1.4rem", color: "rgba(244,243,241,.6)" }}>
            "I promise my emails have fewer animations."
          </p>
        </R>

        <div className="final">
          <div className="end">
            <h2 className="dsp" style={{ opacity: cont ? .3 : 1, transition: "opacity .5s ease" }}>The end.</h2>
            <span className={`strike${struck ? " on" : ""}`} aria-hidden="true" />
          </div>
          <h2 className={`dsp cont${cont ? " on" : ""}`} style={{ fontSize: "clamp(1.8rem,6vw,4.4rem)", color: "var(--red)", marginTop: 10 }}>
            To be continued…
          </h2>
        </div>

        <div className="foot">
          <span>Jagadeeswari Sampath — Product Designer, Bangalore, India</span>
          <span>© 2026 JD</span>
        </div>
        <p className="hand" style={{ fontSize: "1.25rem", color: "rgba(244,243,241,.45)", marginTop: 18 }}>
          made with curiosity, questionable amounts of coffee &amp; a lot of undo.
        </p>
      </div>
    </section>
  );
}

/* ============================================================
   CASE STUDY
   ============================================================ */

function CaseStudy({ id, onClose }) {
  const p = PROJECTS.find((x) => x.id === id);
  useEffect(() => {
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    document.body.style.overflow = id ? "hidden" : "";
    return () => { window.removeEventListener("keydown", esc); document.body.style.overflow = ""; };
  }, [id, onClose]);
  if (!p) return null;

  return (
    <div className="cs" role="dialog" aria-modal="true" aria-label={`${p.name} case study`}>
      <div className="cs-top">
        <span className="lbl">{p.n} / {p.name}</span>
        <button className="btn btn-g" style={{ marginLeft: "auto" }} onClick={onClose}>Close ✕</button>
      </div>
      <div className="wrap" style={{ paddingTop: "clamp(34px,5vw,72px)", paddingBottom: "clamp(50px,8vw,120px)" }}>
        <span className="lbl" style={{ color: "var(--red)" }}>{p.cat}</span>
        <h1 className="dsp" style={{ fontSize: "clamp(2.2rem,6.4vw,5.4rem)", margin: "18px 0 20px", maxWidth: "16ch" }}>{p.head}</h1>
        {p.kicker && <p className="dsp" style={{ fontSize: "clamp(1.8rem,5vw,4rem)", color: "var(--red)", marginBottom: 22 }}>{p.kicker}</p>}
        <p style={{ fontSize: "1.08rem", maxWidth: "58ch", marginBottom: 26 }}>{p.line}</p>
        <div className="chips" style={{ marginBottom: 34 }}>{p.tags.map((t) => <span key={t}>{t}</span>)}</div>

        <div className="nums" style={{ marginBottom: 40 }}>
          {p.metrics.map(([a, b], i) => (
            <div key={b}><b style={{ color: i === 1 ? "var(--red)" : "var(--ink)" }}>{a}</b><span>{b}</span></div>
          ))}
          <div><b style={{ fontSize: "1.15rem", lineHeight: 1.35, fontFamily: "var(--ui)", fontWeight: 700 }}>{p.tags.join(" · ")}</b><span>My role</span></div>
        </div>

        <div className="bubble" style={{ marginBottom: 34 }}>"{p.quote}"</div>

        <div style={{ marginBottom: 46 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 12 }}>
            <span className="lbl">Before / after</span>
            <span className="lbl-sm">Drag the handle</span>
          </div>
          <Compare />
        </div>

        {[["The problem", "The user and business problem, and the evidence it was real."],
          ["Research", "Method, sample, and what you actually did."],
          ["Key insights", "Two or three insights that changed the design."],
          ["The flow", "Before and after — where the steps went."],
          ["Design decisions", "Three decisions and the trade-off behind each."],
          ["Final screens", "Large, clean UI. The part hiring managers scroll for."],
          ["Testing & impact", "What you validated, and what moved."],
          ["Learnings", "What you'd do differently next time."]].map(([h, note], i) => (
            <section key={h} style={{ marginBottom: 44 }}>
              <div style={{ display: "flex", gap: 16, alignItems: "baseline", marginBottom: 12 }}>
                <span className="mono-n">{String(i + 1).padStart(2, "0")}</span>
                <h2 className="dsp" style={{ fontSize: "clamp(1.4rem,2.8vw,2.2rem)" }}>{h}</h2>
              </div>
              <p style={{ color: "#3A3A38", marginBottom: 18, maxWidth: "60ch" }}>{note}</p>
              <div className="slot">Add content + screens</div>
            </section>
          ))}
        <button className="btn" onClick={onClose}>Back to index</button>
      </div>
    </div>
  );
}

